<template>
  <section class="editor-media" :aria-label="label">
    <div class="media-heading"><div><h4>{{ label }} <small>选填</small></h4><p>JPG、PNG 或 WebP · 每张不超过 8MB</p></div><span>{{ count }} / {{ limit }}</span></div>
    <p class="media-save-note">{{ existing ? '选择图片后立即上传，成功后展示在前台。' : '图片先留在当前页面，发布赛事时上传。' }}{{ single ? ' 新图片上传成功后替换原图。' : '' }}</p>
    <div v-if="sheets.length || queue.length" class="media-tiles">
      <div v-for="sheet in sheets" :key="'saved-'+sheet.id" class="media-tile">
        <button v-if="!broken[sheet.id]" class="media-preview" type="button" :aria-label="'预览已上传的' + label" @click="preview(sheetSrc(sheet.id))"><img :src="sheetSrc(sheet.id)" :alt="label" loading="lazy" @error="broken[sheet.id]=true" /><span>放大查看 ↗</span></button>
        <div v-else class="media-broken"><span>缩略图加载失败</span><button type="button" @click="broken[sheet.id]=false">重新加载</button></div>
        <span class="media-state"><i></i>已上传</span><button type="button" :disabled="busy" :aria-label="'移除' + label" @click="$emit('remove',sheet.id)">移除</button>
      </div>
      <div v-for="item in queue" :key="item.url" class="media-tile" :class="{ failed:item.status==='failed' }"><button class="media-preview" type="button" :aria-label="'预览待上传的' + label" @click="preview(item.url)"><img :src="item.url" :alt="'待上传的' + label" /><span>放大查看 ↗</span></button><span class="media-state"><i></i>{{ item.status==='uploading' ? '正在上传…' : item.status==='failed' ? '上传失败 · 文件已保留' : '待发布上传' }}</span><p v-if="item.error" class="media-error" role="alert">{{ item.error }}</p><div><button v-if="item.status==='failed' && existing" type="button" :disabled="busy" @click="$emit('retry',item)">重试上传</button><button type="button" :disabled="busy" @click="$emit('drop',item)">取消</button></div></div>
    </div>
    <label v-if="single || count < limit" class="media-upload" :class="{disabled:busy}"><span class="media-add" aria-hidden="true">＋</span><span>{{ busy ? '正在处理…' : single && count ? '替换' + label : '添加' + label }}</span><input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" :aria-label="'上传' + label" @change="$emit('select',$event)" /></label>
    <dialog ref="dialog" class="media-dialog" :aria-label="label + '大图预览'" @click="dismissBackdrop"><header><span>{{ label }} · 图片预览</span><button type="button" aria-label="关闭图片预览" @click="dialog.close()">关闭 ✕</button></header><img v-if="previewSrc" :src="previewSrc" :alt="label" /></dialog>
  </section>
</template>
<script setup>
import { computed, reactive, ref } from 'vue';
const props=defineProps({label:String,kind:String,sheets:{type:Array,default:()=>[]},queue:{type:Array,default:()=>[]},limit:{type:Number,default:1},busy:Boolean,existing:Boolean,sheetSrc:{type:Function,required:true}});
defineEmits(['select','remove','drop','retry']);
const single=computed(()=>['cover','live'].includes(props.kind));
const count=computed(()=>single.value ? Number(!!(props.sheets.length||props.queue.length)) : props.sheets.length+props.queue.length);
const broken=reactive({}),dialog=ref(null),previewSrc=ref('');
function preview(src){previewSrc.value=src;dialog.value?.showModal();}
function dismissBackdrop(event){if(event.target!==dialog.value)return;const bounds=dialog.value.getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)dialog.value.close();}
</script>
<style scoped>
.editor-media{min-width:0;margin:22px 0 0;padding:17px;border:1px solid #eee5e8;border-radius:13px;background:#fffcfd}.media-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.media-heading h4{margin:0;color:#735362;font-size:13px;font-weight:550;line-height:1.7}.media-heading h4 small{margin-left:5px;color:#b39aa8;font-size:10px;font-weight:400}.media-heading p,.media-save-note{margin:4px 0 0;color:#a08a97;font-size:11px;line-height:1.9}.media-heading>span{flex:none;padding:3px 8px;border-radius:7px;background:#f4ecef;color:#a08a97;font-size:11px;line-height:1.6}.media-save-note{margin:10px 0 12px}.media-tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(118px,1fr));gap:10px}.media-tile{min-width:0;padding:7px;border:1px solid #e9e0e5;border-radius:10px;background:#fff}.media-tile.failed{border-color:#f3b4c3}.media-tile .media-preview{position:relative;display:block;width:100%;min-height:112px;margin:0;padding:0;border:0;border-radius:6px;background:#f7f3f5;overflow:hidden}.media-preview>img{display:block;width:100%;height:112px;object-fit:contain}.media-preview>span{position:absolute;right:4px;bottom:4px;padding:3px 5px;border-radius:4px;background:#ffffffe8;color:#ad788f;font-size:10px;line-height:1.5}.media-state{display:flex;align-items:center;gap:5px;margin-top:7px;color:#8b9e91;font-size:11px;line-height:1.7}.media-state i{flex:none;width:4px;height:4px;border-radius:50%;background:currentColor}.media-tile.failed .media-state,.media-error{color:#bd354f}.media-error{margin:3px 0;overflow-wrap:anywhere;font-size:11px;line-height:1.6}.media-tile>div:not(.media-broken){display:flex;flex-wrap:wrap;gap:4px}.media-tile button{min-width:44px;min-height:44px;padding:7px;border:0;background:transparent;color:#b7738b;font:inherit;font-size:11px;cursor:pointer}.media-broken{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:112px;border-radius:6px;background:#faf5f7;color:#a98b9a;font-size:11px;line-height:1.8}.media-upload{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:7px;min-width:44px;min-height:44px;max-width:100%;margin-top:12px;padding:9px 14px;border:1px dashed #dfb6c0;border-radius:9px;background:#fff8fa;color:#cb5977;font-size:12px;line-height:1.7;cursor:pointer;overflow:hidden}.media-add{font-size:18px;line-height:1}.media-upload input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}.media-upload:focus-within,.media-tile button:focus-visible{outline:2px solid #e84361;outline-offset:2px}.disabled,button:disabled{opacity:.55;cursor:wait}
.media-dialog{width:min(920px,calc(100vw - 28px));max-height:calc(100dvh - 28px);margin:auto;padding:0;border:1px solid #e9dce3;border-radius:15px;background:#fffafc;color:#745365;box-shadow:0 18px 100px #3b183b30;overflow:auto}.media-dialog::backdrop{background:#33222dcc;backdrop-filter:blur(4px)}.media-dialog header{position:sticky;top:0;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 14px;background:#fffafcf5;font-size:12px;line-height:1.8}.media-dialog button{min-width:60px;min-height:44px;padding:8px;border:0;border-radius:8px;background:#f7eaf0;color:#ad526f;font:inherit;font-size:12px}.media-dialog>img{display:block;width:100%;height:auto;min-width:0;object-fit:contain}@media(max-width:400px){.editor-media{padding:13px}.media-tiles{grid-template-columns:repeat(2,minmax(0,1fr))}.media-dialog{max-height:calc(100dvh - 16px);width:calc(100vw - 16px)}}
</style>
